//! Differential ratchet for
//! `src/engine/battleScriptSetforesightOpcode.ts`. Expected complete projected
//! results, controls, and the exact missing-role error are generated by
//! invoking the canonical TypeScript opcode handler; regenerate with
//! `node --experimental-strip-types
//! core-rs/tools/gen-battle-script-setforesight-vectors.mjs`.

use std::collections::BTreeSet;

use factory_core::battle_script_setforesight::{
    apply_battle_script_setforesight, BattleScriptSetforesightBattlerState,
    BattleScriptSetforesightControl, BattleScriptSetforesightRoles, BattleScriptSetforesightRules,
    BATTLE_SCRIPT_SETFORESIGHT_BATTLERS, BATTLE_SCRIPT_SETFORESIGHT_BATTLER_COUNT,
    BATTLE_SCRIPT_STATUS2_FORESIGHT,
};
use factory_core::battle_script_setforesight_vectors_gen::{
    BattleScriptSetforesightVectorCase, BattleScriptSetforesightVectorState,
    BATTLE_SCRIPT_SETFORESIGHT_BATTLER_DOMAIN, BATTLE_SCRIPT_SETFORESIGHT_BRANCH_CENSUS,
    BATTLE_SCRIPT_SETFORESIGHT_CASES, BATTLE_SCRIPT_SETFORESIGHT_CATEGORY_CENSUS,
    BATTLE_SCRIPT_SETFORESIGHT_DOMAIN_CENSUS, BATTLE_SCRIPT_SETFORESIGHT_INPUT_DOMAIN,
    BATTLE_SCRIPT_SETFORESIGHT_STATUS2_EDGE_DOMAIN,
    BATTLE_SCRIPT_SETFORESIGHT_VECTOR_CORPUS_SHA256,
};

fn rules(value: BattleScriptSetforesightVectorState) -> BattleScriptSetforesightRules {
    BattleScriptSetforesightRules {
        battlers: value
            .status2
            .map(|status2| BattleScriptSetforesightBattlerState { status2 }),
        selector_roles: BattleScriptSetforesightRoles { target: value.target },
    }
}

fn vector_state(value: BattleScriptSetforesightRules) -> BattleScriptSetforesightVectorState {
    BattleScriptSetforesightVectorState {
        status2: value.battlers.map(|battler| battler.status2),
        target: value.selector_roles.target,
    }
}

#[test]
fn complete_projected_outputs_controls_and_exact_missing_role_error_match_canonical_typescript() {
    assert_eq!(BATTLE_SCRIPT_SETFORESIGHT_CASES.len(), 27);
    for (case_index, case) in BATTLE_SCRIPT_SETFORESIGHT_CASES.iter().enumerate() {
        execute_case(case_index, case);
    }
}

fn execute_case(case_index: usize, case: &BattleScriptSetforesightVectorCase) {
    let input = rules(case.initial);
    let before = input;
    let mut current = input;
    let mut actual_controls = Vec::new();
    let mut actual_error = None;

    for application in 0..case.applications {
        let prior = current;
        match apply_battle_script_setforesight(&current) {
            Ok(outcome) => {
                actual_controls.push(outcome.control);
                assert_transition_shape(case_index, case, application, prior, outcome);
                current = outcome.rules;
            }
            Err(error) => {
                actual_error = Some(error.to_string());
                break;
            }
        }
    }

    assert_eq!(
        input, before,
        "case {case_index} {}: native transformation mutated input",
        case.label
    );
    match (actual_error, case.expected, case.expected_error) {
        (None, Some(expected), None) => {
            assert_eq!(
                actual_controls.as_slice(),
                case.controls,
                "case {case_index} {}: canonical control sequence",
                case.label,
            );
            assert_eq!(
                actual_controls.len(),
                usize::from(case.applications),
                "case {case_index} {}: successful sequence stopped early",
                case.label,
            );
            assert_eq!(
                vector_state(current),
                expected,
                "case {case_index} {}: complete projected output",
                case.label,
            );
        }
        (Some(error), None, Some(expected_error)) => {
            assert_eq!(
                actual_controls.as_slice(),
                case.controls,
                "case {case_index} {}: error must not produce a control result",
                case.label,
            );
            assert_eq!(
                error, expected_error,
                "case {case_index} {}: exact missing-target error",
                case.label,
            );
        }
        (error, expected, expected_error) => panic!(
            "case {case_index} {}: generated outcome shape disagrees with native result: error={error:?}, expected={expected:?}, expected_error={expected_error:?}",
            case.label,
        ),
    }
}

fn assert_transition_shape(
    case_index: usize,
    case: &BattleScriptSetforesightVectorCase,
    application: u8,
    prior: BattleScriptSetforesightRules,
    outcome: factory_core::battle_script_setforesight::BattleScriptSetforesightOutcome,
) {
    assert_eq!(
        outcome.control,
        BattleScriptSetforesightControl::Advance,
        "case {case_index} {} application {application}: Foresight must advance",
        case.label,
    );
    let target = prior.selector_roles.target.unwrap_or_else(|| {
        panic!(
            "case {case_index} {} application {application}: advance had no target",
            case.label
        )
    });
    assert_eq!(
        outcome.rules.selector_roles, prior.selector_roles,
        "case {case_index} {} application {application}: changed target role",
        case.label,
    );
    for battler in BATTLE_SCRIPT_SETFORESIGHT_BATTLERS {
        if battler != target {
            assert_eq!(
                outcome.rules.battlers[battler.index()],
                prior.battlers[battler.index()],
                "case {case_index} {} application {application}: changed non-target battler {}",
                case.label,
                battler.as_u8(),
            );
        }
    }
    assert_eq!(
        outcome.rules.battlers[target.index()].status2,
        prior.battlers[target.index()].status2 | BATTLE_SCRIPT_STATUS2_FORESIGHT,
        "case {case_index} {} application {application}: did not OR Foresight into target status2",
        case.label,
    );
    assert_eq!(
        outcome.rules.battlers[target.index()].status2 & !BATTLE_SCRIPT_STATUS2_FORESIGHT,
        prior.battlers[target.index()].status2 & !BATTLE_SCRIPT_STATUS2_FORESIGHT,
        "case {case_index} {} application {application}: changed target status2 unrelated bits",
        case.label,
    );
}

#[test]
fn matrix_covers_all_four_targets_clear_set_inputs_and_u32_edges() {
    let matrix = BATTLE_SCRIPT_SETFORESIGHT_CASES
        .iter()
        .filter(|case| case.category == "target-status2-matrix")
        .collect::<Vec<_>>();
    assert_eq!(matrix.len(), 8);
    let matrix_domain = matrix
        .iter()
        .map(|case| {
            let target = case
                .initial
                .target
                .unwrap_or_else(|| panic!("matrix case {} is missing target", case.label));
            (target.as_u8(), case.initial.status2[target.index()])
        })
        .collect::<BTreeSet<_>>();
    let expected_matrix = BATTLE_SCRIPT_SETFORESIGHT_BATTLER_DOMAIN
        .into_iter()
        .flat_map(|target| {
            BATTLE_SCRIPT_SETFORESIGHT_INPUT_DOMAIN
                .into_iter()
                .map(move |status2| (target, status2))
        })
        .collect::<BTreeSet<_>>();
    assert_eq!(matrix_domain, expected_matrix);

    let edges = BATTLE_SCRIPT_SETFORESIGHT_CASES
        .iter()
        .filter(|case| case.category == "u32-status2-edge-matrix")
        .collect::<Vec<_>>();
    assert_eq!(edges.len(), 16);
    let edge_domain = edges
        .iter()
        .map(|case| {
            let target = case
                .initial
                .target
                .unwrap_or_else(|| panic!("edge case {} is missing target", case.label));
            (target.as_u8(), case.initial.status2[target.index()])
        })
        .collect::<BTreeSet<_>>();
    let expected_edges = BATTLE_SCRIPT_SETFORESIGHT_STATUS2_EDGE_DOMAIN
        .into_iter()
        .flat_map(|status2| {
            BATTLE_SCRIPT_SETFORESIGHT_BATTLER_DOMAIN
                .into_iter()
                .map(move |target| (target, status2))
        })
        .collect::<BTreeSet<_>>();
    assert_eq!(edge_domain, expected_edges);
}

#[test]
fn target_only_preservation_missing_target_and_repeated_idempotence_are_pinned() {
    let target_only = BATTLE_SCRIPT_SETFORESIGHT_CASES
        .iter()
        .find(|case| case.label == "target_only_mutation_preserves_siblings_and_unrelated_bits")
        .expect("target-only vector");
    let target_only_expected = target_only.expected.expect("target-only output");
    assert_eq!(
        target_only.initial.target,
        Some(factory_core::battle_script_setforesight::BattleScriptSetforesightBattler::Battler2)
    );
    assert_eq!(target_only_expected.status2[2], 0xa000_0101);
    for battler in [0, 1, 3] {
        assert_eq!(
            target_only_expected.status2[battler], target_only.initial.status2[battler],
            "target-only vector changed sibling {battler}",
        );
    }

    let missing = BATTLE_SCRIPT_SETFORESIGHT_CASES
        .iter()
        .find(|case| case.label == "missing_target_role_precedes_status2_read")
        .expect("missing-target vector");
    assert_eq!(missing.initial.target, None);
    assert_eq!(missing.initial.status2[2], u32::MAX);
    assert_eq!(missing.expected, None);
    assert!(missing.controls.is_empty());
    assert_eq!(
        missing.expected_error,
        Some("Battle Script hit-chain command requires a target role"),
    );

    let repeated = BATTLE_SCRIPT_SETFORESIGHT_CASES
        .iter()
        .find(|case| case.label == "repeated_application_is_idempotent_and_advances_each_time")
        .expect("repeated-application vector");
    assert_eq!(repeated.applications, 2);
    assert_eq!(
        repeated.controls,
        &[
            BattleScriptSetforesightControl::Advance,
            BattleScriptSetforesightControl::Advance,
        ],
    );
    let expected = repeated.expected.expect("repeated output");
    assert_eq!(expected.status2[3], 0x2100_0001);
    assert_eq!(
        expected.status2[3],
        repeated.initial.status2[3] | BATTLE_SCRIPT_STATUS2_FORESIGHT,
        "second Foresight application must leave the initial OR result intact",
    );
}

#[test]
fn fixed_four_slot_domain_u32_edges_and_source_constant_are_retained() {
    assert_eq!(BATTLE_SCRIPT_SETFORESIGHT_BATTLER_COUNT, 4);
    assert_eq!(
        BATTLE_SCRIPT_SETFORESIGHT_BATTLERS.map(|battler| battler.as_u8()),
        BATTLE_SCRIPT_SETFORESIGHT_BATTLER_DOMAIN,
    );
    assert_eq!(BATTLE_SCRIPT_SETFORESIGHT_BATTLER_DOMAIN, [0, 1, 2, 3]);
    assert_eq!(
        BATTLE_SCRIPT_SETFORESIGHT_INPUT_DOMAIN,
        [0x0000_0000, 0x2000_0000],
    );
    assert_eq!(
        BATTLE_SCRIPT_SETFORESIGHT_STATUS2_EDGE_DOMAIN,
        [0x0000_0000, 0xffff_ffff, 0x8000_0000, 0x0100_0001],
    );
    assert_eq!(BATTLE_SCRIPT_STATUS2_FORESIGHT, 0x2000_0000);
}

#[test]
fn domain_category_branch_censuses_and_corpus_hash_are_ratchet_pinned() {
    assert_eq!(
        BATTLE_SCRIPT_SETFORESIGHT_DOMAIN_CENSUS,
        [
            ("battler-slots", 4),
            ("target-role-values", 4),
            ("optional-target-role-values", 5),
            ("status2-u32-values", 4_294_967_296),
            ("status2-edge-values", 4),
            ("foresight-clear-set-inputs", 2),
            ("application-count-values", 2),
            ("typed-missing-target-combinations", 1),
        ],
    );
    assert_eq!(
        BATTLE_SCRIPT_SETFORESIGHT_CATEGORY_CENSUS,
        [
            ("missing-target-role", 1),
            ("repeated-application", 1),
            ("target-only-mutation", 1),
            ("target-status2-matrix", 8),
            ("u32-status2-edge-matrix", 16),
        ],
    );
    assert_eq!(
        BATTLE_SCRIPT_SETFORESIGHT_BRANCH_CENSUS,
        [
            ("advance", 25),
            ("advance-then-advance", 1),
            ("missing-target-role", 1),
        ],
    );
    assert_eq!(
        BATTLE_SCRIPT_SETFORESIGHT_VECTOR_CORPUS_SHA256,
        "fbb38fbd92d927a35a2f5f57e35fb518d7eaae23cb3912ffe5580be972a355cc",
    );
}
